INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (1, 1, 'cpp', '#include <vector>
#include <unordered_map>
using namespace std;

vector<int> twoSum(vector<int>& nums, int target) {
    unordered_map<int,int> seen;
    for (int i = 0; i < (int)nums.size(); i++) {
        int complement = target - nums[i];
        if (seen.count(complement)) return {seen[complement], i};
        seen[nums[i]] = i;
    }
    return {};
}', 'twoSum', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (2, 1, 'cpp', '#include <vector>
using namespace std;

vector<int> twoSum(vector<int>& nums, int target) {
    for (int i = 0; i < (int)nums.size(); i++) {
        for (int j = i + 1; j < (int)nums.size(); j++) {
            if (nums[i] + nums[j] == target) return {i, j};
        }
    }
    return {};
}', 'twoSum', 'brute_force');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (3, 1, 'javascript', 'function twoSum(nums, target) {
    const seen = new Map();
    for (let i = 0; i < nums.length; i++) {
        const complement = target - nums[i];
        if (seen.has(complement)) return [seen.get(complement), i];
        seen.set(nums[i], i);
    }
    return [];
}', 'twoSum', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (4, 1, 'javascript', 'function twoSum(nums, target) {
    for (let i = 0; i < nums.length; i++) {
        for (let j = i + 1; j < nums.length; j++) {
            if (nums[i] + nums[j] === target) return [i, j];
        }
    }
    return [];
}', 'twoSum', 'brute_force');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (5, 1, 'python', 'def twoSum(nums, target):
    seen = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in seen:
            return [seen[complement], i]
        seen[num] = i
    return []', 'twoSum', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (6, 1, 'python', 'def twoSum(nums, target):
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] + nums[j] == target:
                return [i, j]
    return []', 'twoSum', 'brute_force');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (7, 2, 'cpp', '#include <vector>
#include <string>
using namespace std;

vector<string> fizzBuzz(int n) {
    vector<string> result;
    for (int i = 1; i <= n; i++) {
        if (i % 15 == 0) result.push_back("FizzBuzz");
        else if (i % 3 == 0) result.push_back("Fizz");
        else if (i % 5 == 0) result.push_back("Buzz");
        else result.push_back(to_string(i));
    }
    return result;
}', 'fizzBuzz', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (8, 2, 'javascript', 'function fizzBuzz(n) {
    const result = [];
    for (let i = 1; i <= n; i++) {
        if (i % 15 === 0) result.push("FizzBuzz");
        else if (i % 3 === 0) result.push("Fizz");
        else if (i % 5 === 0) result.push("Buzz");
        else result.push(String(i));
    }
    return result;
}', 'fizzBuzz', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (9, 2, 'python', 'def fizzBuzz(n):
    result = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result', 'fizzBuzz', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (10, 3, 'cpp', '#include <string>
#include <algorithm>
using namespace std;

string reverseString(string s) {
    reverse(s.begin(), s.end());
    return s;
}', 'reverseString', 'optimal');
