INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (58, 16, 'cpp', '#include <vector>
#include <algorithm>
using namespace std;

vector<vector<int>> mergeMeetings(vector<vector<int>>& intervals) {
    sort(intervals.begin(), intervals.end());
    vector<vector<int>> result;
    for (auto& iv : intervals) {
        if (!result.empty() && iv[0] <= result.back()[1]) {
            result.back()[1] = max(result.back()[1], iv[1]);
        } else {
            result.push_back(iv);
        }
    }
    return result;
}', 'mergeMeetings', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (59, 16, 'javascript', 'function mergeMeetings(intervals) {
    const sorted = [...intervals].sort((a, b) => a[0] - b[0]);
    const result = [];
    for (const iv of sorted) {
        const last = result[result.length - 1];
        if (last && iv[0] <= last[1]) {
            last[1] = Math.max(last[1], iv[1]);
        } else {
            result.push([...iv]);
        }
    }
    return result;
}', 'mergeMeetings', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (60, 16, 'python', 'def mergeMeetings(intervals):
    intervals = sorted(intervals, key=lambda x: x[0])
    result = []
    for iv in intervals:
        if result and iv[0] <= result[-1][1]:
            result[-1][1] = max(result[-1][1], iv[1])
        else:
            result.append(list(iv))
    return result', 'mergeMeetings', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (61, 17, 'cpp', '#include <vector>
#include <string>
#include <unordered_map>
#include <algorithm>
using namespace std;

vector<vector<string>> groupAnagrams(vector<string>& words) {
    unordered_map<string, int> keyToIndex;
    vector<vector<string>> groups;
    for (auto& word : words) {
        string key = word;
        sort(key.begin(), key.end());
        if (keyToIndex.find(key) == keyToIndex.end()) {
            keyToIndex[key] = groups.size();
            groups.push_back({});
        }
        groups[keyToIndex[key]].push_back(word);
    }
    return groups;
}', 'groupAnagrams', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (62, 17, 'javascript', 'function groupAnagrams(words) {
    const keyToIndex = new Map();
    const groups = [];
    for (const word of words) {
        const key = word.split("").sort().join("");
        if (!keyToIndex.has(key)) {
            keyToIndex.set(key, groups.length);
            groups.push([]);
        }
        groups[keyToIndex.get(key)].push(word);
    }
    return groups;
}', 'groupAnagrams', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (63, 17, 'python', 'def groupAnagrams(words):
    key_to_index = {}
    groups = []
    for word in words:
        key = "".join(sorted(word))
        if key not in key_to_index:
            key_to_index[key] = len(groups)
            groups.append([])
        groups[key_to_index[key]].append(word)
    return groups', 'groupAnagrams', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (64, 18, 'cpp', '#include <string>
#include <unordered_map>
using namespace std;

int longestUniqueSubstring(string s) {
    unordered_map<char, int> lastSeen;
    int start = 0, best = 0;
    for (int i = 0; i < (int)s.size(); i++) {
        if (lastSeen.count(s[i]) && lastSeen[s[i]] >= start) {
            start = lastSeen[s[i]] + 1;
        }
        lastSeen[s[i]] = i;
        best = max(best, i - start + 1);
    }
    return best;
}', 'longestUniqueSubstring', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (65, 18, 'javascript', 'function longestUniqueSubstring(s) {
    const lastSeen = new Map();
    let start = 0, best = 0;
    for (let i = 0; i < s.length; i++) {
        if (lastSeen.has(s[i]) && lastSeen.get(s[i]) >= start) {
            start = lastSeen.get(s[i]) + 1;
        }
        lastSeen.set(s[i], i);
        best = Math.max(best, i - start + 1);
    }
    return best;
}', 'longestUniqueSubstring', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (66, 18, 'python', 'def longestUniqueSubstring(s):
