INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (67, 19, 'cpp', '#include <vector>
using namespace std;

vector<int> nextGreaterElements(vector<int>& nums) {
    vector<int> result(nums.size(), -1);
    vector<int> stack;
    for (int i = 0; i < (int)nums.size(); i++) {
        while (!stack.empty() && nums[stack.back()] < nums[i]) {
            result[stack.back()] = nums[i];
            stack.pop_back();
        }
        stack.push_back(i);
    }
    return result;
}', 'nextGreaterElements', 'optimal');
