INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (73, 21, 'cpp', '#include <vector>
using namespace std;

vector<long long> productExceptSelf(vector<int>& nums) {
    int n = nums.size();
    vector<long long> result(n, 1);
    long long left = 1;
    for (int i = 0; i < n; i++) {
        result[i] = left;
        left *= nums[i];
    }
    long long right = 1;
    for (int i = n - 1; i >= 0; i--) {
        result[i] *= right;
        right *= nums[i];
    }
    return result;
}', 'productExceptSelf', 'optimal');
