INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (76, 22, 'cpp', '#include <vector>
#include <algorithm>
using namespace std;

int maxArea(vector<int>& heights) {
    int left = 0, right = heights.size() - 1;
    int best = 0;
    while (left < right) {
        int area = (right - left) * min(heights[left], heights[right]);
        best = max(best, area);
        if (heights[left] < heights[right]) left++;
        else right--;
    }
    return best;
}', 'maxArea', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (77, 22, 'javascript', 'function maxArea(heights) {
