    let best = 0;
    while (left < right) {
        const area = (right - left) * Math.min(heights[left], heights[right]);
        best = Math.max(best, area);
        if (heights[left] < heights[right]) left++;
        else right--;
    }
    return best;
}', 'maxArea', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (78, 22, 'python', 'def maxArea(heights):
    left, right = 0, len(heights) - 1
    best = 0
    while left < right:
        area = (right - left) * min(heights[left], heights[right])
        best = max(best, area)
        if heights[left] < heights[right]:
            left += 1
        else:
            right -= 1
    return best', 'maxArea', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (79, 23, 'cpp', '#include <vector>
using namespace std;

vector<int> rotateArray(vector<int>& nums, int k) {
    int n = nums.size();
    if (n == 0) return nums;
    k = k % n;
    vector<int> result(n);
    for (int i = 0; i < n; i++) {
        result[(i + k) % n] = nums[i];
    }
    return result;
}', 'rotateArray', 'optimal');
