INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (114, 34, 'python', 'from collections import deque

def maxSlidingWindow(nums, k):
    dq = deque()
    result = []
    for i, n in enumerate(nums):
        while dq and nums[dq[-1]] <= n:
            dq.pop()
        dq.append(i)
        if dq[0] <= i - k:
            dq.popleft()
        if i >= k - 1:
            result.append(nums[dq[0]])
    return result', 'maxSlidingWindow', 'optimal');
