INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (85, 25, 'cpp', '#include <vector>
#include <string>
#include <unordered_map>
#include <algorithm>
using namespace std;

vector<string> topKFrequent(vector<string>& tags, int k) {
    unordered_map<string, int> freq;
    unordered_map<string, int> firstSeen;
    for (int i = 0; i < (int)tags.size(); i++) {
        if (freq.find(tags[i]) == freq.end()) firstSeen[tags[i]] = i;
        freq[tags[i]]++;
    }
    vector<string> unique;
    for (auto& p : freq) unique.push_back(p.first);
    sort(unique.begin(), unique.end(), [&](const string& a, const string& b) {
        if (freq[a] != freq[b]) return freq[a] > freq[b];
        return firstSeen[a] < firstSeen[b];
    });
    unique.resize(min((int)unique.size(), k));
    return unique;
}', 'topKFrequent', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (86, 25, 'javascript', 'function topKFrequent(tags, k) {
    const freq = new Map();
    const firstSeen = new Map();
    for (let i = 0; i < tags.length; i++) {
        if (!freq.has(tags[i])) firstSeen.set(tags[i], i);
        freq.set(tags[i], (freq.get(tags[i]) || 0) + 1);
    }
    const unique = [...freq.keys()];
    unique.sort((a, b) => {
        if (freq.get(a) !== freq.get(b)) return freq.get(b) - freq.get(a);
        return firstSeen.get(a) - firstSeen.get(b);
    });
    return unique.slice(0, k);
}', 'topKFrequent', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (87, 25, 'python', 'def topKFrequent(tags, k):
    freq = {}
    first_seen = {}
    for i, tag in enumerate(tags):
        if tag not in freq:
            first_seen[tag] = i
        freq[tag] = freq.get(tag, 0) + 1
    unique = list(freq.keys())
    unique.sort(key=lambda t: (-freq[t], first_seen[t]))
    return unique[:k]', 'topKFrequent', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (88, 26, 'cpp', '#include <string>
using namespace std;

string longestPalindrome(string s) {
    if (s.empty()) return "";
    int start = 0, maxLen = 1;
    auto expand = [&](int l, int r) {
        while (l >= 0 && r < (int)s.size() && s[l] == s[r]) {
            if (r - l + 1 > maxLen) {
                start = l;
                maxLen = r - l + 1;
            }
            l--; r++;
        }
    };
    for (int i = 0; i < (int)s.size(); i++) {
        expand(i, i);
        expand(i, i + 1);
    }
    return s.substr(start, maxLen);
}', 'longestPalindrome', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (89, 26, 'javascript', 'function longestPalindrome(s) {
    if (s.length === 0) return "";
    let start = 0, maxLen = 1;
    const expand = (l, r) => {
        while (l >= 0 && r < s.length && s[l] === s[r]) {
            if (r - l + 1 > maxLen) {
                start = l;
                maxLen = r - l + 1;
            }
            l--; r++;
        }
    };
    for (let i = 0; i < s.length; i++) {
        expand(i, i);
        expand(i, i + 1);
    }
    return s.substring(start, start + maxLen);
}', 'longestPalindrome', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (90, 26, 'python', 'def longestPalindrome(s):
    if not s:
        return ""
    start, max_len = 0, 1

    def expand(l, r):
        nonlocal start, max_len
        while l >= 0 and r < len(s) and s[l] == s[r]:
            if r - l + 1 > max_len:
                start = l
                max_len = r - l + 1
            l -= 1
            r += 1

    for i in range(len(s)):
        expand(i, i)
        expand(i, i + 1)
    return s[start:start + max_len]', 'longestPalindrome', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (91, 27, 'cpp', '#include <vector>
#include <unordered_map>
using namespace std;

int countSubarraysWithSum(vector<int>& nums, int target) {
    unordered_map<int, int> prefixCount;
    prefixCount[0] = 1;
    long long sum = 0;
    int count = 0;
    for (int num : nums) {
        sum += num;
        if (prefixCount.find(sum - target) != prefixCount.end()) {
            count += prefixCount[sum - target];
        }
        prefixCount[sum]++;
    }
    return count;
}', 'countSubarraysWithSum', 'optimal');
