INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (100, 30, 'cpp', '#include <string>
#include <vector>
#include <unordered_map>
using namespace std;

bool isValidBrackets(string s) {
    unordered_map<char, char> pairs = {{'')'', ''(''}, {'']'', ''[''}, {''}'', ''{''}};
    vector<char> stack;
    for (char c : s) {
        if (c == ''('' || c == ''['' || c == ''{'') {
            stack.push_back(c);
        } else {
            if (stack.empty() || stack.back() != pairs[c]) return false;
            stack.pop_back();
        }
    }
    return stack.empty();
}', 'isValidBrackets', 'optimal');
