INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (106, 32, 'cpp', '#include <vector>
#include <algorithm>
#include <climits>
using namespace std;

double findMedian(vector<int>& a, vector<int>& b) {
    if (a.size() > b.size()) return findMedian(b, a);
    int n = a.size(), m = b.size();
    int lo = 0, hi = n;
    while (lo <= hi) {
        int i = (lo + hi) / 2;
        int j = (n + m + 1) / 2 - i;
        int aLeft = (i == 0) ? INT_MIN : a[i-1];
        int aRight = (i == n) ? INT_MAX : a[i];
        int bLeft = (j == 0) ? INT_MIN : b[j-1];
        int bRight = (j == m) ? INT_MAX : b[j];
        if (aLeft <= bRight && bLeft <= aRight) {
            if ((n + m) % 2 == 0) return (max(aLeft, bLeft) + min(aRight, bRight)) / 2.0;
            return max(aLeft, bLeft);
        } else if (aLeft > bRight) hi = i - 1;
        else lo = i + 1;
    }
    return 0.0;
}', 'findMedian', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (107, 32, 'javascript', 'function findMedian(a, b) {
    if (a.length > b.length) return findMedian(b, a);
    const n = a.length, m = b.length;
    let lo = 0, hi = n;
    while (lo <= hi) {
        const i = Math.floor((lo + hi) / 2);
        const j = Math.floor((n + m + 1) / 2) - i;
        const aLeft = i === 0 ? -Infinity : a[i-1];
        const aRight = i === n ? Infinity : a[i];
        const bLeft = j === 0 ? -Infinity : b[j-1];
        const bRight = j === m ? Infinity : b[j];
        if (aLeft <= bRight && bLeft <= aRight) {
            if ((n + m) % 2 === 0) return (Math.max(aLeft, bLeft) + Math.min(aRight, bRight)) / 2;
            return Math.max(aLeft, bLeft);
        } else if (aLeft > bRight) hi = i - 1;
        else lo = i + 1;
    }
    return 0;
}', 'findMedian', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (108, 32, 'python', 'def findMedian(a, b):
    if len(a) > len(b):
        return findMedian(b, a)
    n, m = len(a), len(b)
    lo, hi = 0, n
    while lo <= hi:
        i = (lo + hi) // 2
        j = (n + m + 1) // 2 - i
        a_left = float("-inf") if i == 0 else a[i-1]
        a_right = float("inf") if i == n else a[i]
        b_left = float("-inf") if j == 0 else b[j-1]
        b_right = float("inf") if j == m else b[j]
        if a_left <= b_right and b_left <= a_right:
            if (n + m) % 2 == 0:
                return (max(a_left, b_left) + min(a_right, b_right)) / 2
            return float(max(a_left, b_left))
        elif a_left > b_right:
            hi = i - 1
        else:
            lo = i + 1
    return 0.0', 'findMedian', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (109, 33, 'cpp', '#include <vector>
#include <algorithm>
using namespace std;

int largestRectangleArea(vector<int>& heights) {
    vector<int> stack;
    int maxArea = 0;
    int n = heights.size();
    for (int i = 0; i <= n; i++) {
        int h = (i == n) ? 0 : heights[i];
        while (!stack.empty() && heights[stack.back()] >= h) {
            int height = heights[stack.back()];
            stack.pop_back();
            int width = stack.empty() ? i : i - stack.back() - 1;
            maxArea = max(maxArea, height * width);
        }
        stack.push_back(i);
    }
    return maxArea;
}', 'largestRectangleArea', 'optimal');
