INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (112, 34, 'cpp', '#include <vector>
#include <deque>
using namespace std;

vector<int> maxSlidingWindow(vector<int>& nums, int k) {
    deque<int> dq;
    vector<int> result;
    for (int i = 0; i < (int)nums.size(); i++) {
        while (!dq.empty() && nums[dq.back()] <= nums[i]) dq.pop_back();
        dq.push_back(i);
        if (dq.front() <= i - k) dq.pop_front();
        if (i >= k - 1) result.push_back(nums[dq.front()]);
    }
    return result;
}', 'maxSlidingWindow', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (113, 34, 'javascript', 'function maxSlidingWindow(nums, k) {
    const dq = [];
    const result = [];
    for (let i = 0; i < nums.length; i++) {
        while (dq.length && nums[dq[dq.length - 1]] <= nums[i]) dq.pop();
        dq.push(i);
        if (dq[0] <= i - k) dq.shift();
        if (i >= k - 1) result.push(nums[dq[0]]);
    }
    return result;
}', 'maxSlidingWindow', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (115, 35, 'cpp', '#include <string>
#include <unordered_map>
#include <climits>
using namespace std;

string minWindow(string s, string t) {
    if (t.empty() || s.empty()) return "";
    unordered_map<char, int> need;
    for (char c : t) need[c]++;
    int missing = t.size();
    int bestLen = INT_MAX, bestStart = 0;
    int left = 0;
    for (int right = 0; right < (int)s.size(); right++) {
        if (need.count(s[right])) {
            if (need[s[right]] > 0) missing--;
            need[s[right]]--;
        }
        while (missing == 0) {
            if (right - left + 1 < bestLen) {
                bestLen = right - left + 1;
                bestStart = left;
            }
            if (need.count(s[left])) {
                need[s[left]]++;
                if (need[s[left]] > 0) missing++;
            }
            left++;
        }
    }
    return bestLen == INT_MAX ? "" : s.substr(bestStart, bestLen);
}', 'minWindow', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (116, 35, 'javascript', 'function minWindow(s, t) {
    if (!t || !s) return "";
    const need = new Map();
    for (const c of t) need.set(c, (need.get(c) || 0) + 1);
    let missing = t.length;
    let bestLen = Infinity, bestStart = 0;
    let left = 0;
    for (let right = 0; right < s.length; right++) {
        const c = s[right];
        if (need.has(c)) {
            if (need.get(c) > 0) missing--;
            need.set(c, need.get(c) - 1);
        }
        while (missing === 0) {
            if (right - left + 1 < bestLen) {
                bestLen = right - left + 1;
                bestStart = left;
            }
            const lc = s[left];
            if (need.has(lc)) {
                need.set(lc, need.get(lc) + 1);
                if (need.get(lc) > 0) missing++;
            }
            left++;
        }
    }
    return bestLen === Infinity ? "" : s.substring(bestStart, bestStart + bestLen);
}', 'minWindow', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (117, 35, 'python', 'def minWindow(s, t):
    if not t or not s:
        return ""
    need = {}
    for c in t:
        need[c] = need.get(c, 0) + 1
    missing = len(t)
    best_len, best_start = float("inf"), 0
    left = 0
    for right, c in enumerate(s):
        if c in need:
            if need[c] > 0:
                missing -= 1
            need[c] -= 1
        while missing == 0:
            if right - left + 1 < best_len:
                best_len, best_start = right - left + 1, left
            lc = s[left]
            if lc in need:
                need[lc] += 1
                if need[lc] > 0:
                    missing += 1
            left += 1
    return "" if best_len == float("inf") else s[best_start:best_start + best_len]', 'minWindow', 'optimal');
