INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (119, 36, 'javascript', 'function lengthOfLIS(nums) {
    const tails = [];
    for (const n of nums) {
        let lo = 0, hi = tails.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (tails[mid] < n) lo = mid + 1;
            else hi = mid;
        }
        if (lo === tails.length) tails.push(n);
        else tails[lo] = n;
    }
    return tails.length;
}', 'lengthOfLIS', 'optimal');
