INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (129, 39, 'python', 'from collections import deque

def canFinish(numCourses, prerequisites):
    graph = [[] for _ in range(numCourses)]
    indegree = [0] * numCourses
    for a, b in prerequisites:
        graph[b].append(a)
        indegree[a] += 1
    queue = deque([i for i in range(numCourses) if indegree[i] == 0])
    visited = 0
    while queue:
        node = queue.popleft()
        visited += 1
        for nxt in graph[node]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                queue.append(nxt)
    return visited == numCourses', 'canFinish', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (130, 40, 'cpp', '#include <vector>
using namespace std;

void sinkIsland(vector<vector<int>>& grid, int r, int c) {
    int rows = grid.size(), cols = grid[0].size();
    vector<pair<int,int>> stack = {{r, c}};
    while (!stack.empty()) {
        auto [cr, cc] = stack.back();
        stack.pop_back();
        if (cr < 0 || cr >= rows || cc < 0 || cc >= cols || grid[cr][cc] != 1) continue;
        grid[cr][cc] = 0;
        stack.push_back({cr+1, cc});
        stack.push_back({cr-1, cc});
        stack.push_back({cr, cc+1});
        stack.push_back({cr, cc-1});
    }
}

int numIslands(vector<vector<int>>& grid) {
    if (grid.empty()) return 0;
    int rows = grid.size(), cols = grid[0].size();
    int count = 0;
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == 1) { count++; sinkIsland(grid, r, c); }
        }
    }
    return count;
}', 'numIslands', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (131, 40, 'javascript', 'function numIslands(grid) {
    if (!grid.length) return 0;
    const rows = grid.length, cols = grid[0].length;
    const sink = (r, c) => {
        const stack = [[r, c]];
        while (stack.length) {
            const [cr, cc] = stack.pop();
            if (cr < 0 || cr >= rows || cc < 0 || cc >= cols || grid[cr][cc] !== 1) continue;
            grid[cr][cc] = 0;
            stack.push([cr+1, cc], [cr-1, cc], [cr, cc+1], [cr, cc-1]);
        }
    };
    let count = 0;
    for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
            if (grid[r][c] === 1) { count++; sink(r, c); }
        }
    }
    return count;
}', 'numIslands', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (132, 40, 'python', 'def numIslands(grid):
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])

    def sink(r, c):
        stack = [(r, c)]
        while stack:
            cr, cc = stack.pop()
            if cr < 0 or cr >= rows or cc < 0 or cc >= cols or grid[cr][cc] != 1:
                continue
            grid[cr][cc] = 0
            stack.extend([(cr+1, cc), (cr-1, cc), (cr, cc+1), (cr, cc-1)])

    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                count += 1
                sink(r, c)
    return count', 'numIslands', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (133, 41, 'cpp', '#include <vector>
#include <queue>
using namespace std;

int kthSmallest(vector<vector<int>>& matrix, int k) {
    int n = matrix.size();
    priority_queue<tuple<int,int,int>, vector<tuple<int,int,int>>, greater<>> heap;
    for (int r = 0; r < n; r++) heap.push({matrix[r][0], r, 0});
    int val = 0;
    for (int i = 0; i < k; i++) {
        auto [v, r, c] = heap.top();
        heap.pop();
        val = v;
        if (c + 1 < n) heap.push({matrix[r][c+1], r, c+1});
    }
    return val;
}', 'kthSmallest', 'optimal');
