vector<int> mergeKArrays(vector<vector<int>>& arrays) {
    priority_queue<tuple<int,int,int>, vector<tuple<int,int,int>>, greater<>> heap;
    for (int i = 0; i < (int)arrays.size(); i++) if (!arrays[i].empty()) heap.push({arrays[i][0], i, 0});
    vector<int> result;
    while (!heap.empty()) {
        auto [val, i, j] = heap.top();
        heap.pop();
        result.push_back(val);
        if (j + 1 < (int)arrays[i].size()) heap.push({arrays[i][j+1], i, j+1});
    }
    return result;
