INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (145, 45, 'cpp', '#include <string>
#include <vector>
#include <unordered_set>
#include <queue>
using namespace std;

int ladderLength(string beginWord, string endWord, vector<string>& wordList) {
    unordered_set<string> wordSet(wordList.begin(), wordList.end());
    if (!wordSet.count(endWord)) return 0;
    queue<pair<string,int>> q;
    q.push({beginWord, 1});
    unordered_set<string> visited = {beginWord};
    while (!q.empty()) {
        auto [word, steps] = q.front(); q.pop();
        if (word == endWord) return steps;
        for (int i = 0; i < (int)word.size(); i++) {
            string candidate = word;
            for (char c = ''a''; c <= ''z''; c++) {
                if (c == word[i]) continue;
                candidate[i] = c;
                if (wordSet.count(candidate) && !visited.count(candidate)) {
                    visited.insert(candidate);
                    q.push({candidate, steps + 1});
                }
            }
        }
    }
    return 0;
}', 'ladderLength', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (146, 45, 'javascript', 'function ladderLength(beginWord, endWord, wordList) {
    const wordSet = new Set(wordList);
    if (!wordSet.has(endWord)) return 0;
    const queue = [[beginWord, 1]];
    const visited = new Set([beginWord]);
    while (queue.length) {
        const [word, steps] = queue.shift();
        if (word === endWord) return steps;
        for (let i = 0; i < word.length; i++) {
            for (let c = 97; c <= 122; c++) {
                const ch = String.fromCharCode(c);
                if (ch === word[i]) continue;
                const candidate = word.slice(0, i) + ch + word.slice(i + 1);
                if (wordSet.has(candidate) && !visited.has(candidate)) {
                    visited.add(candidate);
                    queue.push([candidate, steps + 1]);
                }
            }
        }
    }
    return 0;
}', 'ladderLength', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (147, 45, 'python', 'from collections import deque

def ladderLength(beginWord, endWord, wordList):
    word_set = set(wordList)
    if endWord not in word_set:
        return 0
    queue = deque([(beginWord, 1)])
    visited = {beginWord}
    while queue:
        word, steps = queue.popleft()
        if word == endWord:
            return steps
        for i in range(len(word)):
            for c in "abcdefghijklmnopqrstuvwxyz":
                if c == word[i]:
                    continue
                candidate = word[:i] + c + word[i+1:]
                if candidate in word_set and candidate not in visited:
                    visited.add(candidate)
                    queue.append((candidate, steps + 1))
    return 0', 'ladderLength', 'optimal');
INSERT INTO public.solutions (id, question_id, language, code, function_name, approach) VALUES (101, 30, 'javascript', 'function isValidBrackets(s) {
    const pairs = { ")": "(", "]": "[", "}": "{" };
    const stack = [];
    for (const c of s) {
        if (c === "(" || c === "[" || c === "{") {
            stack.push(c);
        } else {
            if (stack.length === 0 || stack[stack.length - 1] !== pairs[c]) return false;
            stack.pop();
        }
    }
    return stack.length === 0;
}', 'isValidBrackets', 'optimal');


